const unit_wage = ctx.day_rate / day_hours;
const multiple =
	overtime_category === 'SECTION_65_OTHER' ? 1 : ctx.lookup.multiple;
// LPA s.61: hours past the normal day, every hour of a day off.
const plain = get(ctx, 'work.days', []).filter((day) => get(day, 'holiday_kind', '') === '' && ['WORK', 'OFF'].includes(day.day_type));
const quantity = sum(plain.map((day) => Number(get(day, day.day_type === 'OFF' ? 'worked_hours' : 'overtime_hours', 0))));
return unit_wage * multiple * quantity;

