const terms = get(ctx.subject.employment, 'terms', {});
const work = get(terms, 'statutory_work_category', '');
const overtime_category = get(ctx.subject.employment, 'employee_extension_data.term_facts.overtime_category', '');
const normal = get(terms, 'normal_hours_per_day', null);
const day_hours =
	normal != null
		? Number(normal)
		: work === 'HAZARDOUS'
			? ctx.lookup.hazardous_normal_hours_per_day
			: ctx.lookup.normal_hours_per_day;
// LPA s.68: the monthly wage, fixed allowance included (s.5), over 30 normal days.
const unit_wage = ctx.day_rate / day_hours;
const off = (day) => day.day_type === 'REST' || get(day, 'holiday_kind', '') !== '';
// LPA s.62: normal hours on a holiday or rest day. A monthly wage already pays the day, so it adds one times; a daily or hourly wage does not, so two.
const hours = sum(get(ctx, 'work.days', []).filter(off).map((day) => Math.min(Number(get(day, 'worked_hours', 0)), day_hours)));
const multiple = get(terms, 'rate.unit', 'MONTHLY') === 'MONTHLY' ? ctx.lookup.paid_multiple : ctx.lookup.unpaid_multiple;
return unit_wage * multiple * hours;

