const work = get(terms, 'statutory_work_category', '');
const overtime_category = get(ctx.subject.employment, 'employee_extension_data.term_facts.overtime_category', '');
const normal = get(terms, 'normal_hours_per_day', null);
const day_hours =
	normal != null
		? Number(normal)
		: work === 'HAZARDOUS'
			? ctx.lookup.hazardous_normal_hours_per_day
			: ctx.lookup.normal_hours_per_day;
// LPA s.68: the monthly wage, fixed allowance included (s.5), over 30 normal days.
const unit_wage = ctx.day_rate / day_hours;
const multiple =
	overtime_category === 'SECTION_65_OTHER' ? 1 : ctx.lookup.multiple;
const off = (day) => day.day_type === 'REST' || get(day, 'holiday_kind', '') !== '';
// LPA s.63: hours past the normal day on a holiday or rest day.
const quantity = sum(get(ctx, 'work.days', []).filter(off).map((day) => Math.max(0, Number(get(day, 'worked_hours', 0)) - day_hours)));
return unit_wage * multiple * quantity;
